---@class ParkourFactory
local ParkourFactory = Class("ParkourFactory")

function ParkourFactory:__init(poolRoot)
    self.poolMgr = {}
    self.poolRoot = poolRoot
end


--后景
---@param trackGo_ UnityEngine.Transform          轨道根节点
---@param segmentCount_ number                    轨道片段个数
---@param length_ number                          轨道片段长度
---@param speed_ number                           轨道移动速度
---@param imgPaths_ string[]                      后景图片路径
function ParkourFactory:CreateTrack1(trackGo_, segmentCount_, length_, speed_, imgPaths_)
    local segmentGos = self:CreateSegmentGo(trackGo_, segmentCount_)
    local trackSegments = {}
    for _, go in ipairs(segmentGos) do
        local spriteTrackSegment = SpriteTrackSegment.New(go, length_)
        table.insert(trackSegments, spriteTrackSegment)
    end

    local moveSpeed = speed_
    local recycleDis = 1
    local track = Track.New( 1, moveSpeed, recycleDis, trackSegments, 

    -- !! 刷新 trackSegment 时:
        function ( newSegment_, newSegmentIndex_, othDatas_ )

            local imgIndex = newSegmentIndex_ % #imgPaths_ + 1 -- 新后景图的idx, 1 based
            ---@type SpriteTrackSegment
            local spriteTrackSegment = newSegment_
            spriteTrackSegment:RefreshContent(imgPaths_[imgIndex])

        end,
        {} -- othDatas
    )
    return track
end



--中景  使用多个prefab随机的方式
---@param prefabPaths_ string[]                   prefab路径
function ParkourFactory:CreateTrack2(trackGo_, prefabPaths_, segmentCount_, length_, speed_ )
    local segmentGos = self:CreateSegmentGo(trackGo_, segmentCount_)
    local trackSegments = {}
    for _, go in ipairs(segmentGos) do
        local trackSegment = TrackSegment.New(go, length_)
        table.insert(trackSegments, trackSegment)
    end
    
    local moveSpeed = speed_
    local recycleDis = 1

    local track = Track.New( 2, moveSpeed, recycleDis, trackSegments, 

        -- !! 刷新 trackSegment 时:
        function ( newSegment_, newSegmentIndex_, othDatas_ )

            local prefabIndex = math.random(1, #othDatas_.prefabPaths)
            local pool = self:_GetPrefabPool(othDatas_.prefabPaths[prefabIndex])
            local prefabTF = pool:Obtain() -- 从 pool 中取出一个
            ---@type TrackSegment
            local _segment = newSegment_
            prefabTF:SetParent(_segment.transform)
            prefabTF.localPosition = Vector3.zero

            -- 将 segment 上原有的 prefabTF 存入 pool:
            if isNotNull(_segment.prefabTF) then
                _segment.prefabTF:SetParent(self.poolRoot)
                pool:Free(_segment.prefabTF) -- 存入 pool
            end
            
            CfUtils.SetActive(_segment.prefabTF ,false)
            CfUtils.SetActive(prefabTF,true)
            _segment.prefabTF = prefabTF
            _segment.prefabPool = pool
        end,
        -- othDatas
        {
            prefabPaths = prefabPaths_ -- !! 通过这个来支持在 无限模式下 动态更换 track2 的图集
        }
    )

    return track
end



--操作层
function ParkourFactory:CreateInteractionTrackSegment(trackGo_, segmentCount_, length_, trackMapReader_,speed_)
    local segmentGos = self:CreateSegmentGo(trackGo_, segmentCount_)
    local trackSegments = {}
    for _, go in ipairs(segmentGos) do
        local interactionTrackSegment = InteractionTrackSegment.New(go, length_, trackMapReader_)
        table.insert(trackSegments, interactionTrackSegment)
    end
    
    local moveSpeed = speed_
    local recycleDis = 10
    local track = Track.New( 3, moveSpeed, recycleDis, trackSegments)
    return track
end


---@private
function ParkourFactory:CreateSegmentGo( trackGo_,segmentCount_ )
    local segmentGos = {}
    for i = 1, segmentCount_ do
        local go = trackGo_.transform:Find("Segment"..i)
        if isNull(go) then
            go = GameObject("Segment"..i)
            go.transform:SetParent(trackGo_.transform)
        end
        table.insert(segmentGos, go)
    end
    return segmentGos
end


---@return Pool
function ParkourFactory:GetTrackItemPool(path_)
    if not self.poolMgr[path_] then
        self.poolMgr[path_] = Pool.New(function ()
            ---@type TrackItem
            local result
            ResourceModule.LoadGameObjectSync(path_, function (go)
                if go then
                    go:SetActive(false)
                    result = go:GetComponent(typeof(LuaBehaviour)).Env
                end
            end)
            return result
        end,1)
    end
    return self.poolMgr[path_]
end


---@return Pool
function ParkourFactory:_GetPrefabPool(path_)
    if not self.poolMgr[path_] then
        self.poolMgr[path_] = Pool.New(function ()
            local result
            ResourceModule.LoadGameObjectSync(path_, function (go)
                if go then
                    go:SetActive(false)
                    result = go.transform
                end
            end)
            return result
        end,1)
    end
    return self.poolMgr[path_]
end


function ParkourFactory:GenerateTrackItem(path_, callback_)
    ---@type Pool
    local pool = self:GetTrackItemPool(path_)
    ---@type TrackItem
    local trackItem = pool:Obtain()
    trackItem.recycled = false
    trackItem:SetPool(pool, self.poolRoot)
    if callback_ then
        callback_(trackItem)
    end
end

return ParkourFactory